import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.BTLSZHNB.js";const u=JSON.parse('{"title":"Conformance","description":"","frontmatter":{},"headers":[],"relativePath":"conformance/index.md","filePath":"conformance/index.md"}'),o={name:"conformance/index.md"};function i(s,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="conformance" tabindex="-1">Conformance <a class="header-anchor" href="#conformance" aria-label="Permalink to &quot;Conformance&quot;">​</a></h1><p>The retained v1alpha2 candidate compatibility evidence is executable Go characterization:</p><ul><li><code>internal/provider/*_test.go</code> asserts that the published provider v2.0.0 exposes exactly the nine independently authored v1alpha2 candidates, and covers typed schema behavior, validation, CRUD, import, state refresh, and the absence of plan-time remote mutation; the source tree additionally registers exactly the v1alpha3-lane Edge Platform Family resources for the unpublished v2.1 source candidate — and no generic carrier, which is itself asserted (<a href="./../spec/decisions/0013-v1alpha3-lane-ships-in-provider-v2-1.html">decision 0013</a>, <a href="./../spec/decisions/0021-third-party-forms-and-contract-distribution.html">decision 0021</a>);</li><li><code>internal/client/client_test.go</code> asserts discovery, capability negotiation, preview/apply evidence, error envelopes, observation, and deletion;</li><li><code>examples/resources/</code> contains one formatted HCL example for every registered resource, with no exceptions: every provider resource is derived from a Form, so every one has an example.</li></ul><p>Run:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">go test ./...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">go vet ./...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tofu fmt -check -recursive examples</span></span></code></pre></div><h2 id="current-provider-v2-lifecycle-evidence" tabindex="-1">Current provider-v2 lifecycle evidence <a class="header-anchor" href="#current-provider-v2-lifecycle-evidence" aria-label="Permalink to &quot;Current provider-v2 lifecycle evidence&quot;">​</a></h2><p><code>cmd/provider-lifecycle-conformance</code> builds the real provider-v2 candidate binary and drives every declared v1alpha2 typed resource through a Terraform-compatible CLI against an in-process versioned Form host. The regression covers create, read plus observe, mutable update with state-generation fencing, explicit refresh, native import, CLI import, drift mapping from observe evidence, delete, exact response-identity rejection, and replacement plans for immutable names, SQL engine, and vector dimensions. The data-only compatibility report binds the CLI product/version, exact canonical provider FQN, provider schema digest, embedded candidate-set digest, release-descriptor provider version/binary digest, CLI executable basename, and CLI binary SHA-256 without leaking a host-local path. CI runs the reviewed OpenTofu and Terraform versions as one fail-closed matrix:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">go run ./cmd/provider-lifecycle-conformance verify --cli tofu</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">go run ./cmd/provider-lifecycle-conformance verify --cli /path/to/terraform</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">go run ./cmd/provider-lifecycle-conformance matrix --opentofu tofu --terraform terraform</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">go run ./cmd/provider-lifecycle-conformance provider-reports \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --cli terraform --output-dir /tmp/takoform-provider-reports \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --source-commit &quot;$(git rev-parse HEAD)&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">go run ./cmd/provider-lifecycle-conformance provider-reports \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --cli tofu --output-dir /tmp/takoform-opentofu-provider-reports \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --source-commit &quot;$(git rev-parse HEAD)&quot;</span></span></code></pre></div><p><code>provider-reports</code> first verifies the exact generated v1alpha2 candidate package set. It executes each canonical positive fixture and every declared negative fixture through provider protocol v6. Desired negatives include a one-at-a-time omission of <code>name</code>, artifact <code>source</code>, required <code>connections</code>, and every Form-specific required field; each must return a provider diagnostic before the in-process Form host receives a mutation. The observed negative lets the host return <code>OtherKind/&lt;name&gt;</code> and requires the provider to reject the response before it enters state. Both classes are reported as portable <code>invalid_argument</code>. The external host report binds and executes the exact desired-stage subset; the provider report covers that subset plus the observed-stage response rejection. The retained historical report schema does not claim output-stage negative coverage until a runner contract exists. These reports prove conformance behavior only; they grant no lifecycle state or host authority.</p><p>The command combines those per-package observations with the independently executed full lifecycle checks and writes one strict RFC 8785 <code>takoform.standard-provider-runner-report@v2</code> document per kind. It refuses to write under <code>admission/</code>, signs nothing, publishes nothing, and cannot change Form lifecycle or host activation. The retained <code>external-required</code> field is Legacy data, not a pending central gate. Its output directory must be new or empty. Each report subject records the one canonical provider identity, <code>provider:registry.terraform.io/tako0614/takoform</code>, regardless of whether OpenTofu or Terraform executes it.</p><p>The matrix retains the machine classification <code>generic-lifecycle-candidate</code> with <code>publicationReady: false</code> and <code>bindingStatus: exact-structural-candidate-set</code> because changing an old report format would falsify historical compatibility. Those labels are not current Form lifecycle states. The matrix does not publish a checked-in passed report or claim Form maturity. It requires Terraform <code>1.15.8</code> and OpenTofu <code>1.12.3</code> under the same canonical identity, <code>registry.terraform.io/tako0614/takoform</code>, then requires identical provider schema, exact FormRef/package identity, and lifecycle evidence. Immutable publication proves distribution only. Hosts separately publish support for an exact FormRef and activate it under their own policy; neither action changes the Form&#39;s project lifecycle state.</p><h2 id="schema-derivation-gate" tabindex="-1">Schema derivation gate <a class="header-anchor" href="#schema-derivation-gate" aria-label="Permalink to &quot;Schema derivation gate&quot;">​</a></h2><p>The provider-v2 schema, v1alpha2 Form Definition, and candidate conformance fixtures are all derived from one current catalog declaration, so drift between them is a build failure rather than something a checked-in fixture corpus has to notice later. <code>go run ./cmd/standard-form-conformance verify</code> regenerates nothing: it reads the committed packages, re-verifies their bytes, and inspects the actual provider resource schema for every declared Form, including that each field the definition calls immutable really forces replacement.</p><h2 id="retained-v1alpha1-legacy-package-corpus" tabindex="-1">Retained v1alpha1 Legacy package corpus <a class="header-anchor" href="#retained-v1alpha1-legacy-package-corpus" aria-label="Permalink to &quot;Retained v1alpha1 Legacy package corpus&quot;">​</a></h2><p><code>form-package-v1/</code> is a separate corpus for the portable package layer. It includes one valid closed ExampleStore package. Each package has one exact FormRef, one definition, one positive desired fixture, closed desired/observed schemas, and no host authority fields. Tests pin every package/schema digest and reject an unknown host extension and one kind-specific invalid fixture.</p><p><code>form-package-v1/positive/standard/</code> contains the historical generated package for every one of the 34 v1alpha1 Legacy Forms. It is retained to authenticate those exact bytes; it is not a source for v1alpha2 candidates and never starts a new current version line. <code>go run ./cmd/standard-form-conformance verify</code> validates package bytes and fixtures and inspects the actual provider resource structure. It does not run the Terraform protocol lifecycle or a conforming host, and this repository intentionally contains no locally synthesized passed admission JSON.</p><p>The machine-readable inventory&#39;s <code>structural-candidate</code>, <code>structural-only</code>, <code>external-required</code>, Definition <code>status: standard</code>, and <code>portable-standard</code> values are immutable historical document facts. They are not a current queue, rank, maturity state, or missing approval. Current v1alpha2 maturity comes only from <code>forms/lifecycle.json</code>.</p><p>The same corpus contains negative fixtures for duplicate names, invalid Unicode scalar sequences, negative zero, credentials, operator fields, target/capacity, price/billing/SKU, executable code fields, plural API/private/SSH/signing key and manager identifier derivatives, traversal, absolute paths, and backslashes. The ExampleStore package also fixes boundary-safe words such as <code>apiKeysight</code>, <code>privateerKeys</code>, and <code>managerialIds</code>. Filesystem-only symlink, executable-bit, and device/pipe cases are covered by library tests. Unit tests additionally prove linear admission of a shared-reference DAG, fail-closed schema proof depth/operation limits, the 16,384-evaluation fixture-validation budget through the real directory verifier, cardinality amplification through <code>items</code>, <code>contains</code>, <code>additionalProperties</code>, and <code>propertyNames</code>, embedded content transformation rejection, and the independent limits of 32 positive plus 32 negative fixtures per Form Definition.</p><p>Run it with:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">go run ./cmd/form-package conformance</span></span></code></pre></div><p>The corpus also contains <code>positive/interface-declaration</code>. It proves exact <code>(name, version)</code> identity (including two versions with one name), exact non-secret document validation, <code>required</code> metadata, literal/output/resource-URI/host mapping sources, explicit JSON <code>null</code>, and RFC 6901 root and escaped pointers. Negative cases cover mapping grammar, invalid pointer escapes, and documents that do not satisfy their declared schema. Materialization, authorization, and lifecycle remain host work.</p><p>The Form Definition limits apply independently to each fixture class: at most 32 positive fixtures and at most 32 negative fixtures, not 32 combined. Every retained Legacy Form and every current candidate stays within the negative limit without combining or dropping required-field omission cases.</p><p>The retained Legacy corpus manifest contains 36 positive packages (one ExampleStore, one interface-declaration package, and 34 historical generated packages) and 51 negative cases. Passing this corpus proves the local Legacy data contract only. It is not signature, publisher, remote-install, host-activation, retention/revocation, lifecycle idempotency, or cross-host/kind-standardization evidence. Those require their own role-specific execution and, for admission, authenticated external evidence.</p><h2 id="portable-host-evidence" tabindex="-1">Portable host evidence <a class="header-anchor" href="#portable-host-evidence" aria-label="Permalink to &quot;Portable host evidence&quot;">​</a></h2><p><code>portable-host-v1/</code> is the frozen provider-v1 Legacy corpus. It pins the v1alpha1 discovery/API paths and exact Legacy ObjectBucket identity so retained publication evidence remains independently verifiable.</p><p><code>portable-host-v2/</code> is the retained provider-v2 corpus. It pins the separate v1alpha2 discovery/API paths, an exact EdgeWorker candidate and all of its desired-negative fixtures, a Schedule-to-EdgeWorker connection probe, concurrency/idempotency rules, stable errors, and required cross-repo black-box checks. The retained-lane provider client consumes this contract in adversarial HTTP tests.</p><p><code>portable-host-v3/</code> is the Host API v1alpha3 corpus consumed by the provider v2.1 client lane. It pins the v1alpha3 discovery/API paths, the closed 26-code error taxonomy with its exact HTTP status map and 4-code retryable set, the uid/generation/revision identity rules, the closed portable condition-reason vocabulary, and exact Edge Family probe identities (ModuleWorker, EdgeKVNamespace, AtLeastOnceQueue, WorkerBundle, WorkerVersion, WorkerDeployment, WorkerCronTrigger, QueueConsumer) with their registry package digests plus byte-pinned desired-negative fixtures. <code>self-test --contract conformance/portable-host-v3</code> starts a deterministic reference host over the real candidate definitions and drives the complete 73-check matrix over real HTTP: exact discovery and availability, validate/prepare with RFC 8785 prepare binding and substitution rejection (a prepare against an existing resource requires the update generation fence, and a fence-less or stale prepare is rejected), uid minting and delete-then-recreate uid change, generation fences versus revision fences (including a host-side status touch that advances only the revision), packageDigest as audit-only evidence that never enters identity or queries, one kind name in two namespaced groups, revision-role update rejection, cross-resource relation resolution before mutation — every reference a Form derives from its desired schema, not only typed bindings — pinned by target uid, with <code>dependency_in_use</code> on the deletion of any referenced target, <code>ExternalChange</code> when a target is destroyed and recreated under the same name — which a spec-identical re-apply repairs, re-pinning every relation while generation stands still and only the revision moves — and binding contracts verified against allowedTargetForms, the target Form&#39;s providedInterfaces, and the source role, import validated exactly like apply, cross-resource semantics the Forms declare in prose but only a host can enforce (WorkerDeployment weights summing to 10000; a cron trigger or queue consumer refused with <code>unsupported_capability</code> until some WorkerVersion declares the matching handler), 202 Operation polling with Retry-After plus terminal replay and cancel — with every fence, binding resolution, and blob requirement re-verified at commit time rather than at accept time — the content-addressed artifact upload/commit flow feeding a WorkerBundle apply including its manifest reject list and commit-time size binding, the closed SpaceID grammar, support profiles free of price/SKU/region/quota, concurrent mutation of unrelated resources, and idempotency isolation across principals, tenants, and Spaces. It also drives the operability rules of <a href="./../spec/decisions/0018-the-host-api-is-deployable-behind-ordinary-infrastructure.html">decision 0018</a>: a namespaced group served as two ordinary path segments on the resource, form-definition, and support routes, with no request target percent-encoding a slash; an operation id and an upload id answered <code>operation_not_found</code> and <code>artifact_missing</code> for every other principal and tenant while the owner&#39;s record survives untouched; and a content address that is a name rather than an entitlement — another tenant reads neither the manifest nor the blob, a second principal of the HOLDING tenant reads both, and the other tenant that uploads the same bytes is told they are missing for IT before committing the identical, physically deduplicated artifact. The same holding rule governs USING an address rather than only reading one: a bundle whose desired state references a manifest the caller&#39;s tenant does not hold is refused <code>artifact_missing</code> before any mutation, on apply and on import, storing nothing, while a second principal of the holding tenant references it successfully and the other tenant references it once it has supplied the bytes itself. Probing every stable error uses the runner-only <code>Takoform-Conformance-Probe</code> header (<code>error:&lt;code&gt;</code>, <code>async</code>, <code>touch-status</code>, <code>external-change</code>); it is disposable-adapter transport, never a production surface. <code>external-change</code> performs one delete as an out-of-band backend change so a runner can reach the one state relation protection otherwise makes unreachable. As with the other lanes, a passing local report is implementation evidence for the runner and reference host only: it is explicitly <code>publicationReady: false</code> and is never publication, admission, host support, or Form maturity evidence.</p><p>The executable runner is <code>go run ./cmd/portable-host-conformance</code>. Its <code>self-test</code> command starts a disposable deterministic host and drives the actual HTTP discovery, Form availability, preview, apply, read, observe, refresh, import, delete, and read-only Interface endpoints. It rejects a host that accepts a preview plan for different spec bytes, advances a generation on an exact idempotent replay, ignores a stale fence, changes an exact response/ETag on replay, or exposes a required Interface before Ready or after delete.</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">go run ./cmd/portable-host-conformance self-test</span></span></code></pre></div><p>The matrix also exercises all stable error envelopes over HTTP. Errors such as permission or backend failure have no provider-neutral way to induce, so a disposable external conformance endpoint uses the runner-only <code>Takoform-Conformance-Probe-Error</code> header. The same disposable adapter accepts the closed authorization probes <code>Takoform-Conformance-Probe-Authorization: credential-revoked</code>, <code>permission-revoked</code>, and <code>policy-revoked</code>, and must process each current denial in the normal authentication/authorization path before any replay lookup. After every denial, the runner repeats the unprobed request and requires the original cached success byte-for-byte, proving that a denial did not overwrite or poison the success record.</p><p>Plan binding has two explicitly separated evidence classes. Valid substitutions of desired spec, Space, and an existing Resource generation are pure black-box HTTP checks. The remaining one-field substitutions would ordinarily be rejected by route, envelope, or exact-Form validation before reaching plan binding, so the disposable adapter accepts the closed-enum <code>Takoform-Conformance-Probe-Plan-Binding</code> header. It passes that request directly to the same canonical plan-binding function used by normal apply and returns <code>Takoform-Conformance-Probe-Plan-Binding-Result: rejected</code> with <code>invalid_argument</code> only when that function rejects it. If the function accepts the substitution, the adapter returns HTTP 204 with <code>accepted-no-mutation</code> and must not execute a fence, mutate state, or record a replay. Unknown values fail as <code>invalid_argument</code>, and authentication and authorization run before this instrumentation. The report records pure black-box and instrumented-adapter inputs separately.</p><p>The disposable adapter also accepts <code>Takoform-Conformance-Probe-Raw-JSON: duplicate-error-code</code> and returns the contract&#39;s exact malformed error envelope. The runner must reject it during complete raw-document I-JSON validation, before decoding stable error semantics. Unknown raw-probe values fail as <code>invalid_argument</code>.</p><p>All four probe headers are disposable-adapter transport, are not part of the host API, and must not be implemented or enabled on production. The first two token variables must name distinct authenticated principals in the same tenant. The third must represent the first principal in another tenant. All three credentials must be distinct and authorized for the complete test lifecycle in both exact runner Spaces. For the cross-tenant isolation probe only, both tenant contexts must address the same disposable Resource namespace; an independently executed create then deterministically collides instead of returning the first tenant&#39;s cached success. Run the same matrix against such an endpoint with:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">go run ./cmd/portable-host-conformance run \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --endpoint https://disposable-host.example \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --token-env TAKOFORM_CONFORMANCE_TOKEN \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --alternate-token-env TAKOFORM_CONFORMANCE_ALTERNATE_TOKEN \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --alternate-tenant-token-env TAKOFORM_CONFORMANCE_ALTERNATE_TENANT_TOKEN</span></span></code></pre></div><p>Both reports are explicitly <code>publicationReady: false</code>. The local reference report proves the executable runner, not an external host. Admission still requires a signed report from the host workflow that actually executed its backend lifecycle. Desired-stage negative fixtures are host request evidence; observed-stage rejection is provider/host-response evidence because the portable API intentionally has no operation for injecting observed state.</p><p>The required sequence includes create collision, mutable update, stale update/delete/observe/refresh rejection, exact replay, retry-code semantics, the fixed stable-code/HTTP mapping, the exact <code>1..9223372036854775807</code> decimal generation range, and Interface readiness. It also rejects plan substitution field by field for desired spec, Resource identity/name, Space, generation, every exact FormRef field, and package digest. Name instrumentation uses the matching alternate Resource URL, while generation uses a real update after the Resource has advanced, so neither can pass because of a create fence or URL/body mismatch. Replay evidence proves that another principal cannot address the first principal&#39;s cached success, that the same principal in another tenant cannot address it, and that current authentication, permission, and policy denial each precede replay lookup. The same Resource name and exact Form are then created and read in <code>runnerInput.alternateSpace</code> with the primary Space&#39;s Idempotency-Key; neither Resource state nor replay records may cross the Space boundary.</p><p>Before lifecycle mutation, raw adversarial requests additionally prove that unknown top-level envelope fields, unknown metadata fields, authority-shaped desired fields, duplicate <code>metadata.space</code>, duplicate <code>metadata.resourceVersion</code>, duplicate <code>spec</code>, and invalid UTF-8 fail closed. The duplicate cases are rejected by shared complete-document I-JSON validation before typed decoding. The report also records the three replay isolation dimensions, the three current denial codes, and preservation of the original successful replay after every denial.</p><p><code>interfaceDeclarations.checks</code> is an exact executed subset of <code>requiredRunnerChecks</code>, and the report repeats that exact list as Interface evidence. Over real HTTP the runner rejects unknown, duplicate, and partially paired Interface query parameters; requires an explicit Space without substituting another one; exercises omitted-version success only for a unique visible declaration; creates a second Ready Resource in the same Space to require <code>interface_instance_ambiguous</code>; and re-reads an unchanged projection after POST, PUT, PATCH, and DELETE are rejected on both portable Interface routes. The visible declaration must equal the exact Form descriptor, satisfy its <code>documentSchema</code>, contain no portable authority fields, appear only with a Ready Resource, and disappear after deletion. When present, <code>resourceUri</code> must pass the shared credential-free HTTPS grammar; the adversarial runner rejects userinfo, query, fragment, plaintext HTTP, and Unicode-hostname substitutions.</p><p>The selected ObjectBucket fixture has one required descriptor at one version, so this runner does not claim that it induced multi-version identity ambiguity, optional-descriptor omission, or activation rejection on a feature-disabled host. Their wire rules remain normative, and the stable ambiguity error envelopes are exercised, but causal host evidence for those cases needs a separate exact package fixture.</p><p>It treats drift only as validated observed evidence and defines no drift operation or portable audit endpoint.</p>`,40)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
